using System;using System.Collections.Generic;using UnityEngine;
class EntityVehicle{public Vehicle vehicle=new Vehicle();public Transform ModelTransform;}
class Vehicle{public ItemValue item=new ItemValue();public ItemValue GetUpdatedItemValue()=>item;}
class ItemValue{public string tint="255,255,255";public string GetPropertyOverride(string key,string fallback)=>tint;}
static class GameManager{public static bool IsDedicatedServer;}
static class Block{public const string PropTintColor="TintColor";public static Vector3 StringToVector3(string value){var p=value.Split(',');return new Vector3(float.Parse(p[0]),float.Parse(p[1]),float.Parse(p[2]));}}
static class RebirthCamperBodyVisibility{public const string PickupPaint="REBIRTHPickupOnlyPaint";}
namespace UnityEngine{
struct Vector3{public float x,y,z;public Vector3(float a,float b,float c){x=a;y=b;z=c;}}
struct Color{public float r,g,b,a;public Color(float R,float G,float B,float A){r=R;g=G;b=B;a=A;}public static bool operator==(Color x,Color y)=>x.r==y.r&&x.g==y.g&&x.b==y.b&&x.a==y.a;public static bool operator!=(Color x,Color y)=>!(x==y);public override bool Equals(object o)=>o is Color c&&this==c;public override int GetHashCode()=>r.GetHashCode();}
static class Shader{public static int PropertyToID(string s)=>s.GetHashCode();}
class Material{public Color color;public bool HasProperty(int id)=>true;}
class MaterialPropertyBlock{internal Dictionary<int,Color> colors=new Dictionary<int,Color>();public bool isEmpty=>colors.Count==0;public void Clear()=>colors.Clear();public Color GetColor(int id)=>colors.TryGetValue(id,out var c)?c:default;public void SetColor(int id,Color c)=>colors[id]=c;public void Copy(MaterialPropertyBlock p){Clear();foreach(var pair in p.colors)colors[pair.Key]=pair.Value;}}
class Renderer{public Material sharedMaterial=new Material();public Material[] sharedMaterials=>new[]{sharedMaterial};public readonly Dictionary<int,MaterialPropertyBlock> blocks=new Dictionary<int,MaterialPropertyBlock>();public int writes;public void GetPropertyBlock(MaterialPropertyBlock p,int index=-1){p.Clear();if(blocks.TryGetValue(index,out var b))p.Copy(b);}public void SetPropertyBlock(MaterialPropertyBlock p,int index=-1){if(!blocks.TryGetValue(index,out var b))blocks[index]=b=new MaterialPropertyBlock();b.Copy(p);writes++;}}
class Transform{public Transform child;public Renderer[] panels;public Transform Find(string path)=>child;public T[] GetComponentsInChildren<T>(bool inactive)=>(T[])(object)panels;}
}
class Program{
static int checks;static void Check(bool pass,string name){if(!pass)throw new Exception(name);checks++;}
static Color Read(Renderer r,int id,int slot=-1){var p=new MaterialPropertyBlock();r.GetPropertyBlock(p,slot);return p.GetColor(id);}
static void Main(){int tint=Shader.PropertyToID("_Color"),other=Shader.PropertyToID("_PatternEnabled");var panels=new Renderer[9];for(int i=0;i<9;i++)panels[i]=new Renderer();var original=new Material{color=new Color(255,255,255,1)};foreach(var p in panels)p.sharedMaterial=original;var floor=new Renderer{sharedMaterial=new Material{color=new Color(.08f,.08f,.08f,1)}};var model=new Transform{child=new Transform{panels=panels}};var entity=new EntityVehicle{ModelTransform=model};var block=new MaterialPropertyBlock();block.SetColor(other,new Color(1,2,3,4));panels[0].SetPropertyBlock(block);panels[1].SetPropertyBlock(block,0);
foreach(var value in new[]{"255,0,0","0,0,255","255,255,255"}){entity.vehicle.item.tint=value;RebirthCamperPickupPaint.Apply(entity);var v=Block.StringToVector3(value);var desired=new Color(v.x,v.y,v.z,1);foreach(var p in panels){Check(Read(p,tint)==desired,"Every addition follows native byte tint "+value);Check(ReferenceEquals(p.sharedMaterial,original),"Material ownership retained");Check(p.sharedMaterial.color==new Color(255,255,255,1),"Stale shared material left intact");}Check(Read(panels[1],tint,0)==desired,"Indexed override synced");Check(Read(panels[0],other)==new Color(1,2,3,4),"Other renderer override preserved");Check(Read(panels[1],other,0)==new Color(1,2,3,4),"Other indexed override preserved");Check(floor.sharedMaterial.color==new Color(.08f,.08f,.08f,1)&&floor.blocks.Count==0,"Black floor untouched");}
int before=panels[0].writes;RebirthCamperPickupPaint.Apply(entity);Check(panels[0].writes==before,"No repeated unchanged writes");panels[0].SetPropertyBlock(new MaterialPropertyBlock());RebirthCamperPickupPaint.Apply(entity);Check(Read(panels[0],tint)==new Color(255,255,255,1),"Rebuild cleared MPB recovers");entity.ModelTransform=new Transform{child=new Transform{panels=new[]{new Renderer()}}};entity.vehicle.item.tint="0,0,255";RebirthCamperPickupPaint.Apply(entity);Check(Read(entity.ModelTransform.child.panels[0],tint)==new Color(0,0,255,1),"Model replacement rebinds");GameManager.IsDedicatedServer=true;entity.vehicle.item.tint="255,0,0";RebirthCamperPickupPaint.Apply(entity);Check(Read(entity.ModelTransform.child.panels[0],tint)==new Color(0,0,255,1),"Dedicated skips rendering");Console.WriteLine("PASS "+checks+" actual-production paint assertions");}}
